        var bag = FlairJSONBag()
        bag.encodeTexture(self.image, for: "uImage")
        bag.encodeFloat(self.lift, for: "uLift")
        bag.encodeFloat(self.whiten, for: "uWhiten")
        bag.encodeFloat(self.skinGuard, for: "uSkinGuard")
